def transform(grid):
    # Exact tiling of the 8-cells by 2x2 squares and L triominoes.
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # The L color records its missing corner.
    color_for_missing = {
        (0, 0): 2,  # top-left
        (1, 0): 3,  # bottom-left
        (0, 1): 4,  # top-right
        (1, 1): 5,  # bottom-right
    }

    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r, c+1), (r+1, c), (r+1, c+1)}
            placements.append((block, 1))
            for missing in block:
                piece = block - {missing}
                placements.append((piece, color_for_missing[(missing[0]-r, missing[1]-c)]))

    def search(left, chosen):
        if not left:
            return chosen
        cell = min(left)
        options = [(piece, color) for piece, color in placements
                   if cell in piece and piece <= left]
        # Prefer squares, then larger/top-left anchored shapes for a stable tiling.
        options.sort(key=lambda x: (len(x[0]) != 4, min(x[0])))
        for piece, color in options:
            result = search(left - piece, chosen + [(piece, color)])
            if result is not None:
                return result
        return None

    tiling = search(cells, [])
    if tiling is None:
        return [row[:] for row in grid]
    for piece, color in tiling:
        for r, c in piece:
            out[r][c] = color
    return out
